+public class DefaultUnsortableTopNEncoderTests extends ESTestCase {
+    public void testVIntSmall() {
+        testVInt(between(0, 127), 1);
+    }
+
+    public void testVIntMed() {
+        testVInt(between(128, 16383), 2);
+    }
