+        Row row(int position, Row spare) {
+            Row result;
+            if (spare == null) {
+                result = new Row();
+            } else {
+                result = spare;
+                result.keys.clear();
+                result.orderByCompositeKeyAscending.clear();
+                result.values.clear();
+            }
+
+            writeKey(position, result);
+            writeValues(position, result.values);
+
+            return result;
+        }
