+    public record TopNOperatorFactory(
+        int topCount,
+        List<ElementType> elementTypes,
+        List<TopNEncoder> encoders,
+        List<SortOrder> sortOrders,
+        int maxPageSize
+    ) implements OperatorFactory {
+        public TopNOperatorFactory
