+    public TopNOperator(
+        int topCount,
+        List<ElementType> elementTypes,
+        List<TopNEncoder> encoders,
+        List<SortOrder> sortOrders,
+        int maxPageSize
+    ) {
+        this.maxPageSize = maxPageSize;
